import {cardEscape as e} from './debt-card.mjs';
const money=n=>new Intl.NumberFormat('vi-VN').format(n)+' ₫';
const shapes={home:'<path d="m3 11 9-8 9 8v10h-6v-7H9v7H3Z"/>',discover:'<circle cx="12" cy="12" r="10"/><path d="m16 8-3 5-5 3 3-5Z"/>',community:'<circle cx="9" cy="7" r="3"/><path d="M2 21v-3a7 7 0 0 1 14 0v3M17 4a3 3 0 0 1 0 6M22 21v-3a6 6 0 0 0-4-6"/>',debts:'<path d="m2 7 10-5 10 5-10 5Zm0 5 10 5 10-5M2 17l10 5 10-5"/>',messages:'<path d="M21 11a9 9 0 0 1-9 9H5l-4 3 2-7a9 9 0 1 1 18-5Z"/>',heart:'<path d="M12 21C-8 9 5-4 12 5c7-9 20 4 0 16Z"/>',book:'<path d="M12 5v17M2 3c4-1 7 0 10 2 3-2 6-3 10-2v16c-4-1-7 0-10 2-3-2-6-3-10-2Z"/>',impact:'<path d="M4 20V12M10 20V7M16 20V3M22 20V1"/>',shield:'<path d="m12 2 9 4v6c0 5-5 8-9 10-4-2-9-5-9-10V6Zm-4 9 3 3 5-6"/>',saved:'<path d="m12 2 3 7 8 1-6 5 2 8-7-4-7 4 2-8-6-5 8-1Z"/>'};
export const di=name=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${shapes[name]||shapes.heart}</svg>`;
export function discoverIntro(){return `<section class="discover-intro"><span class="discover-eyebrow">DISCOVER & SUPPORT</span><h1>Real People,<br>Real Stories</h1><div class="discover-underline"></div><p class="discover-lead">Discover real debt journeys, hear their stories, and lend a helping hand to someone on their path to debt freedom.</p><div class="discover-values">${[['heart','Support with Purpose','Một chút đồng hành, một khởi đầu mới.'],['book','Stories that Inspire','Lắng nghe câu chuyện phía sau mỗi khoản nợ.'],['community','A Caring Community','Cùng nhau xây dựng một cộng đồng tử tế.']].map(([icon,title,copy])=>`<div><span>${di(icon)}</span><div><h2>${title}</h2><p>${copy}</p></div></div>`).join('')}</div><div class="discover-landscape"><div class="discover-land-sun"></div><div class="discover-land-hill"></div><div class="discover-land-hill second"></div><span>Every small kindness<br>opens a new path.</span></div></section>`;}
export function discoverCommunity({stories,saved}){return `<section class="discover-community"><section class="discover-panel"><div class="discover-panel-title"><span>${di('impact')}</span><div><h2>Our Community Impact</h2><p>Small steps. Shared hope.</p></div></div><div class="discover-stat"><span>${di('community')}</span><div><strong>${stories}</strong><p>Câu chuyện trong bản thử</p></div></div><div class="discover-stat"><span>${di('saved')}</span><div><strong>${saved}</strong><p>Thẻ bạn đã lưu</p></div></div><div class="discover-stat"><span>${di('shield')}</span><div><strong>Coming soon</strong><p>Xác minh hồ sơ và thanh toán</p></div></div><small class="discover-data-note">Dữ liệu trên thiết bị · Không phải số liệu giao dịch thực.</small></section><section class="discover-quote discover-panel"><span>“</span><blockquote>A little help doesn't just change a day.<br>It can open a whole new chapter.</blockquote><div><img src="assets/debtfreelately-mark-clean.png" alt=""><p>DebtFreeLately<small>No one gets debt-free alone.</small></p></div></section><section class="discover-panel discover-activity"><div class="discover-panel-title"><span>${di('community')}</span><div><h2>Your Community Activity</h2></div></div><div><span>${di('saved')}</span><p>${saved?`Bạn đã lưu ${saved} câu chuyện để xem lại.`:'Lưu một câu chuyện để bắt đầu đồng hành.'}</p></div><div><span>${di('heart')}</span><p>Thanh toán chưa được tích hợp.<small>Chưa có giao dịch được ghi nhận.</small></p></div><div><span>${di('messages')}</span><p>Tìm hiểu thêm bằng cách nhắn tin với chủ thẻ.<small>Tin nhắn hiện là bản thử trên thiết bị.</small></p></div></section></section>`;}
export function discoveryCard(card,{post,saved}){const photo=card.photo;const percent=post.amount?Math.min(100,Math.round((post.pledged||0)/post.amount*100)):0;return `<article class="discovery-debt-card"><div class="discovery-photo ${photo?'portrait':'landscape'}"><img src="${e(photo||'assets/journey-mountains.png')}" alt="${photo?'Ảnh đại diện của '+e(card.name):'Phong cảnh minh họa'}"><span class="discovery-category">${di('book')}${e(post.category)}</span><span class="discovery-verified">${di('shield')}${post.sample?'Hồ sơ mẫu':post.approved?'Đã duyệt':'Chưa xác minh'}</span></div><div class="discovery-card-body"><div class="discovery-person">${photo?`<img src="${e(photo)}" alt="">`:''}<div><h2>${e(card.name)}${card.age?`, ${e(card.age)}`:''}</h2>${card.location?`<p>⌖ ${e(card.location)}</p>`:''}</div></div>${card.debts.map(d=>`<h3 class="discovery-title">${e(d.title)} <span>🌱</span></h3>${Number.isSafeInteger(d.amount)?`<p class="discovery-debt-amount">${new Intl.NumberFormat('vi-VN').format(d.amount)} ₫</p>`:''}${d.story?`<p class="discovery-story">${e(d.story)}</p>`:''}`).join('')}<div class="discovery-card-facts"><div>${di('debts')}<p>Khoản nợ<strong>${e(post.category)}</strong></p></div></div><p class="discovery-learn-hint">Tap the app logo to learn more about this card.</p><div class="discovery-card-actions"><button data-dc="skip" data-id="${e(post.id)}" aria-label="Bỏ qua thẻ"><span>×</span> Skip</button><button data-dc="save" data-id="${e(post.id)}" aria-label="${saved?'Bỏ lưu thẻ':'Lưu thẻ'}" aria-pressed="${saved}">${di('saved')}${saved?'Saved':'Save'}</button><button data-dc="detail" data-id="${e(post.id)}" aria-label="Xem thêm thông tin chi tiết"><img src="assets/debtfreelately-mark-clean.png" alt="Logo DebtFreeLately"> Support</button></div></div></article>`;}

